def move_files_in_dated_folders(container_name, relative_path, folders_to_check):

    '''
        Function to move excel files which end with date to their respective dated folders

        Args:
        container_name: (string) The name of the container
        relative_path: (string) The path to the folder to process 
        folders_to_check: (string array) An array of folder names to process

        Returns:
        None

        Actions:
        Moves excel files which end with a date to their respective dated folders.

    '''

    storage_account = mssparkutils.notebook.run('/utils/py_utils_get_storage_account')
    folders = mssparkutils.fs.ls("abfss://"+container_name+"@"+storage_account+relative_path)

    file_extension = '.xlsx'
    incorrect_formatted_files = []

    for folder in folders:
        if not folder.isDir or folder.name not in folders_to_check:
            continue

        files = mssparkutils.fs.ls(folder.path)

        for file in files:
            if not file.isFile or not is_excel(file.name):
                continue

            # getting last 8 characters before the extension to extract date
            date = file.name[len(file_extension) * -1 - 8:len(file_extension) * -1]

            if is_valid_date(date):
                date_formatted = format_date(date)
                dest_dir = "{}/{}/{}".format(folder.path, date_formatted, file.name)
                mssparkutils.fs.mv(file.path, dest_dir, True, overwrite=True)
            else:
                incorrect_formatted_files.append(file.path)

    if(len(incorrect_formatted_files) == 0):
        logger.info('All files have been successfully moved')
    else:
        logger.info('Unable to move the following files because of incorrect date format in the filename. Should be YYYYMDD')
        logger.info('\n'.join(incorrect_formatted_files))


def is_excel(file):
    return file.endswith('.xlsx')


def is_valid_date(date):
    try:
        datetime.date.fromisoformat(format_date(date))
        return True
    except:
        return False


def format_date(date):
    return datetime.datetime.strptime(date, '%Y%m%d').strftime('%Y-%m-%d')

def delete_table(db_name, table_name):
    import logging
    logger = logging.getLogger(__name__)
    from pyspark.sql import SparkSession
    from notebookutils import mssparkutils
    spark = SparkSession.builder.getOrCreate()
    if spark._jsparkSession.catalog().tableExists(db_name, table_name):
        table_details = spark.sql(f"DESCRIBE DETAIL {db_name}.{table_name}").toPandas()
        if len(table_details) > 1:
            raise RuntimeError("too many locations associated with the table!")
        else:
            loc = table_details['location'][0]
            mssparkutils.fs.rm(loc, True)
            spark.sql(f"DROP TABLE IF EXISTS {db_name}.{table_name}")
    else:
        logger.info("Table does not exist")

