def fetch_all_notebooks():
    notebooks = []


    base_url = "https://pins-synw-odw-dev-uks.dev.azuresynapse.net"
    api_version = "2020-12-01"

    url = f'{base_url}/notebooks?api-version={api_version}'

    # Set the headers with the access token
    headers = {
        'Authorization': f'Bearer {access_token}'
    }

    while url:
        response = requests.get(url, headers=headers)
        if response.status_code == 200:
            data = response.json()
            notebooks.extend(data['value'])  # Add current page of notebooks
            url = data.get('nextLink')  # Get the next page URL, if any
        else:
            print(f"Failed to list notebooks: {response.status_code}")
            print(response.text)
            break

    return notebooks

