def get_absence_hrs(days, original_hrs, start, end, ws):
    ws = work_schedule[work_schedule["work_schedule_rule"] == ws]
    if len(ws) == 0:
        return str(original_hrs)
    if len(ws) > 1:
        ws = ws.iloc[0]

    sum = 0

    try:
        for d in pd.bdate_range(start, end):
            day_short_name = d.day_name()[0:2]
            hrs = float(ws[day_short_name.lower()])
            if str(d)[:10] in bh['date'].values:
                if include_bank_holidays:
                    sum += hrs
            else:
                sum += days*hrs if days < 1 else hrs
    except:
        return str(original_hrs)

    return str(sum)

